import{_ as e,o as n,c as s,ai as t}from"./chunks/framework.Ai2o9gNv.js";const i="/assets/image-20260702213322447.BR-uPnWM.png",r="/assets/image-20260702213602351.B0aX2mem.png",l="/assets/image-20260702213625994.COACDtsE.png",o="/assets/image-20260702213703379.CyzSGEz1.png",b=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/AI 时代程序员的作弊器  智谱 ZRead 源码阅读工具/AI 时代程序员的作弊器  智谱 ZRead 源码阅读工具.md","filePath":"AI人工智能/AI 时代程序员的作弊器  智谱 ZRead 源码阅读工具/AI 时代程序员的作弊器  智谱 ZRead 源码阅读工具.md","lastUpdated":1782999818000,"__rawMarkdown":"## AI 时代程序员的\\"作弊器\\"  智谱 ZRead 源码阅读工具\\n\\n\\n\\n## 前言\\n\\n大家好，我是**万少**，一个深耕鸿蒙和 AI 的技术人员。\\n\\n随着 AI 时代的发展，相关工具涌现的速度可太快了。很多时候一些开源工具研发出来了，但可能文档还**没来得及**跟着更新。那么万少就会去用 **AI 读取源码**的方式来学习使用，这里主要分享一下 *智谱* 推出的源码阅读工具 **ZRead**。\\n\\n## Zread.ai\\n\\n> https://zread.ai/\\n\\nZRead 是智谱推出的源码阅读工具，它支持**在线添加仓库**和**本地生成 wiki**两种使用方式。万少习惯在本地使用它，本地使用需要安装它的 CLI 工具。\\n\\n![](assets/image-20260702213322447.png)\\n\\n## 下载安装 ZreadCli\\n\\n```\\nnpm install -g zread_cli\\n```\\n\\n安装好了之后，在你的源码目录中启动终端，然后输入\\n\\n```\\nzread\\n```\\n\\nCLI 会根据当前状态提示下一步，例如**登录**、**生成文档**或**打开已有文档**。\\n\\n这里我以 **DevEcoCli** 源码仓库为例：\\n\\n![](assets/image-20260702213602351.png)\\n\\n---\\n\\n生成的文档效果：\\n\\n![](assets/image-20260702213625994.png)\\n\\n可以看到，左侧是目录，中间是正文，其中仓库中的代码关系还会帮你描绘 **SVG 图**，方便理解。\\n\\n![](assets/image-20260702213703379.png)\\n\\n## 也可以集成 skill 的方式来使用它\\n\\n```\\ninstall this skill https://github.com/ZreadAI/zread-skill\\n```\\n\\n> 用自然语言使用 zread-skill 即可\\n\\n## 写在最后\\n\\nAI 时代正在带来各行各业的变革，**多了解一些，总归是有好处的**。\\n\\n毕竟，未来的程序员，可能不是写代码最快的那个，而是**最会用 AI 的那个**。\\n"}'),p={name:"AI人工智能/AI 时代程序员的作弊器  智谱 ZRead 源码阅读工具/AI 时代程序员的作弊器  智谱 ZRead 源码阅读工具.md"};function d(c,a,g,h,m,_){return n(),s("div",null,[...a[0]||(a[0]=[t("",26)])])}const k=e(p,[["render",d]]);export{b as __pageData,k as default};
